package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdGenerators;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class BeanDeserializerFactory_createBeanDeserializer_TriageGen0Test {

    private BeanDeserializerFactory factory;
    private DeserializationContext ctxt;
    private DeserializationConfig config;
    private JavaType type;
    private BeanDescription beanDesc;
    private TypeFactory typeFactory;

    // A concrete class to test bean deserialization
    public static class TestBean {
        public String name;
    }

    // An abstract class to test materialization
    public static abstract class AbstractBean {
        public String value;
    }

    public static class ConcreteBean extends AbstractBean {}

    // An exception class to test Throwable handling
    public static class TestException extends RuntimeException {}

    @Before
    public void setUp() {
        // Using a spy to mock protected methods of the class under test
        factory = Mockito.spy(new BeanDeserializerFactory(null));
        ctxt = mock(DeserializationContext.class);
        config = mock(DeserializationConfig.class);
        typeFactory = TypeFactory.defaultInstance();

        when(ctxt.getConfig()).thenReturn(config);

        type = typeFactory.constructType(TestBean.class);
        beanDesc = mock(BeanDescription.class);
    }

    @Test
    public void testCreateBeanDeserializer_CustomOverride() throws JsonMappingException {
        JsonDeserializer<Object> customDeserializer = new StdDeserializer<Object>(Object.class) {};

        doReturn(customDeserializer).when(factory)._findCustomBeanDeserializer(any(), any(), any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(customDeserializer, result);
        verify(factory)._findCustomBeanDeserializer(type, config, beanDesc);
    }

    @Test
    public void testCreateBeanDeserializer_ThrowableType() throws JsonMappingException {
        JavaType exceptionType = typeFactory.constructType(TestException.class);
        JsonDeserializer<Object> throwableDeserializer = mock(JsonDeserializer.class);

        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        doReturn(throwableDeserializer).when(factory).buildThrowableDeserializer(any(), any(), any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, exceptionType, beanDesc);

        assertEquals(throwableDeserializer, result);
    }

    @Test
    public void testCreateBeanDeserializer_AbstractTypeWithMaterialization() throws JsonMappingException {
        JavaType abstractType = typeFactory.constructType(AbstractBean.class);
        JavaType concreteType = typeFactory.constructType(ConcreteBean.class);
        JsonDeserializer<Object> beanDeserializer = mock(JsonDeserializer.class);

        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        doReturn(concreteType).when(factory).materializeAbstractType(any(), eq(abstractType), any());
        doReturn(config.introspect(concreteType)).when(config).introspect(concreteType);
        doReturn(beanDeserializer).when(factory).buildBeanDeserializer(any(), eq(concreteType), any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, abstractType, beanDesc);

        assertEquals(beanDeserializer, result);
    }

    @Test
    public void testCreateBeanDeserializer_StandardDeserializerFound() throws JsonMappingException {
        JsonDeserializer<Object> stdDeserializer = mock(JsonDeserializer.class);

        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        doReturn(null).when(factory).materializeAbstractType(any(), any(), any());
        doReturn(stdDeserializer).when(factory).findStdDeserializer(any(), any(), any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(stdDeserializer, result);
    }

    @Test
    public void testCreateBeanDeserializer_NotPotentialBeanType() throws JsonMappingException {
        // Use String which is not a "potential bean type" in many logic contexts
        JavaType stringType = typeFactory.constructType(String.class);

        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        doReturn(null).when(factory).findStdDeserializer(any(), any(), any());
        doReturn(false).when(factory).isPotentialBeanType(String.class);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, stringType, beanDesc);

        assertNull(result);
    }

    @Test
    public void testCreateBeanDeserializer_BuildBeanDeserializer() throws JsonMappingException {
        JsonDeserializer<Object> beanDeserializer = mock(JsonDeserializer.class);

        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        doReturn(null).when(factory).findStdDeserializer(any(), any(), any());
        doReturn(true).when(factory).isPotentialBeanType(TestBean.class);
        doReturn(beanDeserializer).when(factory).buildBeanDeserializer(any(), eq(type), any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(beanDeserializer, result);
    }

    @Test
    public void testCreateBeanDeserializer_AbstractPrimitiveCheck() throws JsonMappingException {
        // JavaType doesn't directly support "abstract primitive" in a simple way, 
        // but we can mock the type to satisfy the condition logic.
        JavaType mockType = mock(JavaType.class);
        when(mockType.isThrowable()).thenReturn(false);
        when(mockType.isAbstract()).thenReturn(true);
        when(mockType.isPrimitive()).thenReturn(true);

        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        doReturn(null).when(factory).findStdDeserializer(any(), any(), any());
        doReturn(false).when(factory).isPotentialBeanType(any());

        factory.createBeanDeserializer(ctxt, mockType, beanDesc);

        // Verify that materializeAbstractType was NOT called because isPrimitive() is true
        verify(factory, never()).materializeAbstractType(any(), any(), any());
    }
}
